def transform(grid):
    a=[r[:] for r in grid]; h=len(a); w=len(a[0]); bg=max(set(sum(a,[])),key=sum(sum(v==x for v in row) for row in a for x in set(row)))
    ink=[x for x in set(sum(a,[])) if x!=bg]
    # boundary colors project across the row/column spans occupied at an edge
    for c in (0,w-1):
        color=a[0][c] if any(a[r][c]!=bg for r in range(h)) else bg
        if color!=bg:
            for r in range(h):
                if a[r][c]==color:
                    for j in range(w):
                        if j!=c: a[r][j]=color
    return a
